from timeit import repeat
def rescans(rows):
    return {topic: sum(m for t, m in rows if t == topic) for topic in dict.fromkeys(t for t, _ in rows)}
def one_pass(rows):
    result = {}
    for topic, minutes in rows:
        result[topic] = result.get(topic, 0) + minutes
    return result
rows = [(f"topic-{i % 50}", i % 30) for i in range(2000)]
assert rescans(rows) == one_pass(rows)
assert rescans([]) == one_pass([]) == {}
scan_times = repeat(lambda: rescans(rows), number=2, repeat=3)
pass_times = repeat(lambda: one_pass(rows), number=2, repeat=3)
assert len(scan_times) == len(pass_times) == 3
print("equivalence and timing checks passed")

